// Что лежит в зашифрованной cookie сессии админки (nuxt-auth-utils).
// Только id: имя, роль и права каждый раз читаем из базы — если владелец поменял права
// или отключил сотрудника, это действует сразу, а не после повторного входа.
declare module '#auth-utils' {
  interface User {
    id: number
  }
}

export {}
